WITH left_oracle AS (WITH benchmark AS (SELECT b.volume FROM `newzl`.`hsj_stock_hq_basic` AS b INNER JOIN `newzl`.`hsj_stock_code_info` AS s ON s.mktcode=b.mktcode AND s.tgtcode=b.tgtcode WHERE s.name='贵州茅台' AND b.bizdate='2026-04-14') SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS b CROSS JOIN benchmark AS q WHERE b.mktcode=1 AND b.bizdate='2026-04-14' AND b.volume>q.volume), right_oracle AS (WITH event_rows AS (SELECT mktcode,tgtcode,bizdate,ma3>ma30 AND LAG(ma3) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate)<=LAG(ma30) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS matched FROM `newzl`.`hsj_stock_hq_basic_technical`), qualified AS (SELECT mktcode,tgtcode FROM event_rows WHERE bizdate>=DATE_TRUNC('2026-04-14','YEAR') AND bizdate<='2026-04-14' GROUP BY mktcode,tgtcode HAVING SUM(CASE WHEN matched THEN 1 ELSE 0 END)>0) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14'), left_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM left_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE 1=1 AND q.volume>=100), right_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM right_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=1 AND q.volume>=10) SELECT mktcode,tgtcode,bizdate FROM left_filtered UNION DISTINCT SELECT mktcode,tgtcode,bizdate FROM right_filtered;
